<?php foreach (FORMULARIOS as $index => $name): ?>
<div class="form-summary-row available"><span class="form-number"><?= str_pad((string) ($index + 1), 2, '0', STR_PAD_LEFT) ?></span><div><strong><?= e($name) ?></strong><?php if ($index > 0 && $index < 5): ?><small><?= $index === 4 ? 'Caja Blanca' : 'Caja Negra' ?> · Vinculado a un caso de prueba</small><?php elseif ($index === 5): ?><small>Nivel proyecto · Versiones y cronograma</small><?php elseif ($index > 5 && $index < 9): ?><small>Nivel proyecto · <?= ['Evaluación sumativa', 'Evaluación formativa', 'Organización de evidencias'][$index - 6] ?></small><?php elseif ($index === 9): ?><small>Gestión de defectos · Caso relacionado opcional</small><?php endif; ?></div><a class="text-link" href="<?= e(url(FORMULARIO_RUTAS[$index])) ?>">Disponible →</a></div>
<?php endforeach; ?>
